def union_sorted(a: list[int], b: list[int]) -> list[int]:
    i = j = 0
    out: list[int] = []

    def push(x: int) -> None:
        if not out or out[-1] != x:
            out.append(x)

    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            push(a[i]); i += 1
        else:
            push(b[j]); j += 1
    while i < len(a):
        push(a[i]); i += 1
    while j < len(b):
        push(b[j]); j += 1
    return out
